def unique_latest(records):
    best = {}
    order = []
    for rec in records:
        rid = rec['id']
        if rid not in best:
            best[rid] = rec
            order.append(rid)
        else:
            if rec['timestamp'] >= best[rid]['timestamp']:
                best[rid] = rec
    return [best[rid] for rid in order]
