import copy


def merge(base, overlay):
    """Recursively merge two JSON-like dictionaries into a new deep-independent result.

    - When both sides have a dict for the same key, they are merged recursively.
    - In all other cases the overlay value replaces the base value.
    - A None value in the overlay does NOT delete the key; it simply replaces
      the previous value with None.
    - No input is mutated and no nested reference is shared with the result.
    """
    result = {}

    for key in base:
        if key in overlay:
            b_val = base[key]
            o_val = overlay[key]
            if isinstance(b_val, dict) and isinstance(o_val, dict):
                result[key] = merge(b_val, o_val)
            else:
                result[key] = copy.deepcopy(o_val)
        else:
            result[key] = copy.deepcopy(base[key])

    for key in overlay:
        if key not in base:
            result[key] = copy.deepcopy(overlay[key])

    return result
```

