def flatten(value):
    """Flatten a nested dictionary with string keys into dot-separated keys.

    - Lists and scalar leaves are preserved as values.
    - An empty dict leaf is represented as {} at its path.
    - An empty root produces {}.
    - Keys never contain dots.
    - Does not mutate the input.
    """
    if not isinstance(value, dict):
        return value

    result = {}
    for k, v in value.items():
        if isinstance(v, dict):
            if not v:
                result[k] = {}
            else:
                for sub_key, sub_val in flatten(v).items():
                    result[f"{k}.{sub_key}"] = sub_val
        else:
            result[k] = v
    return result
```

