def normalize(path: str) -> str:
    """Normalize an absolute POSIX-like path.

    - Rejects non-absolute paths with ValueError.
    - Collapses repeated slashes.
    - Ignores '.' segments.
    - Resolves '..' segments without going above root.
    - Returns '/' for root; no trailing slash elsewhere.
    - No filesystem access.
    """
    if not path.startswith('/'):
        raise ValueError(f"path must be absolute, got: {path!r}")

    stack = []
    for part in path.split('/'):
        if part in ('', '.'):
            continue
        elif part == '..':
            if stack:
                stack.pop()
        else:
            stack.append(part)

    return '/' + '/'.join(stack)
```

