def pack(items, max_bytes):
    if max_bytes < 1:
        raise ValueError("max_bytes must be >= 1")
    if not items:
        return []

    for item in items:
        if len(item.encode("utf-8")) > max_bytes:
            raise ValueError(f"Item {item!r} exceeds max_bytes")

    result = []
    current = []
    current_size = 0

    for item in items:
        item_size = len(item.encode("utf-8"))
        if current_size + item_size > max_bytes:
            result.append(current)
            current = []
            current_size = 0
        current.append(item)
        current_size += item_size

    result.append(current)
    return result
```

