import heapq


def order(deps):
    nodes = set(deps.keys())
    for prereqs in deps.values():
        nodes.update(prereqs)

    remaining = {node: 0 for node in nodes}
    dependents = {node: [] for node in nodes}

    for node, prereqs in deps.items():
        remaining[node] = len(prereqs)
        for p in prereqs:
            dependents[p].append(node)

    heap = []
    for node in nodes:
        if remaining[node] == 0:
            heapq.heappush(heap, node)

    result = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for dep in dependents[node]:
            remaining[dep] -= 1
            if remaining[dep] == 0:
                heapq.heappush(heap, dep)

    if len(result) != len(nodes):
        raise ValueError("Cycle detected")

    return result
```

